Object.assign(functionalChords,{viadd9:{degree:6,type:'minor',kind:'madd9',functional:'6m(add9)'},ii7:{degree:2,type:'minor',kind:'m7',functional:'2m7'},iii7:{degree:3,type:'minor',kind:'m7',functional:'3m7'},vi7:{degree:6,type:'minor',kind:'m7',functional:'6m7'},IVmaj7:{degree:4,type:'major',kind:'maj7',functional:'4maj7'},Iadd9:{degree:1,type:'major',kind:'add9',functional:'1add9'},V6:{degree:5,type:'major',kind:'6',functional:'5(6)'},Vsus4:{degree:5,type:'major',kind:'sus4',functional:'5sus4'},I69:{degree:1,type:'major',kind:'69',functional:'1(6/9)'}});
perfChord=function(bar){const c=functionalChords[bar.chord],r=perfRoot(),delta=majorSteps[c.degree-1],kind=chords.find(x=>x.id===(c.kind||c.type)),pc=(r[1]+delta)%12,letter=letters[(letters.indexOf(r[0][0])+c.degree-1)%7],d=((pc-natural[letter]+18)%12)-6;const name=letter+({[-2]:'𝄫',[-1]:'♭',0:'',1:'♯',2:'𝄪'}[d])+kind.suffix;let base=48+r[1]+delta;while(base>55+r[1])base-=12;return {name,notes:kind.intervals.map(v=>base+v),functional:c.functional||({I:'1',ii:'2m',iii:'3m',IV:'4',V:'5',vi:'6m','vii°':'7dim'}[bar.chord])}};
performanceScore=composedSong;performanceBar=0;$('#performanceTempo').value=66;$('#performanceSong').options[0].textContent=composedSong.title+' · 原创完整弹唱曲';
