const scoreTools=document.createElement('div');scoreTools.className='score-tools';scoreTools.innerHTML='<p>上：和弦级数 / 实际和弦　中：旋律简谱　下：逐字歌词</p><button id="downloadScore">下载完整简谱 SVG</button><button id="downloadSongData">下载曲谱数据</button><button id="downloadPiano">导出钢琴示范 WAV</button><label><input id="scoreFollow" type="checkbox" checked> 跟随播放</label>';$('#performanceScore').before(scoreTools);
const esc=scoreEscape;
function svgText(x,y,text,cls='',extra=''){return `<text x="${x}" y="${y}" class="${cls}" ${extra}>${esc(text)}</text>`}
function systemSVG(bars,start,count,width=1100){const pad=30,barWidth=(width-pad*2)/count;let out='';bars.forEach((bar,k)=>{const x0=pad+k*barWidth,xend=x0+barWidth,inner=barWidth-40,notes=bar.melody,ch=perfChord(bar);let beat=0;const positions=notes.map(note=>{const x=x0+20+(beat+.27)/4*inner;beat+=note.beats;return x});out+=`<g class="engraved-bar" data-perf-bar="${start+k}" tabindex="0" role="button" aria-label="第 ${start+k+1} 小节，${esc(ch.name)}"><rect x="${x0}" y="12" width="${barWidth}" height="142" class="bar-wash"/>${svgText(x0+10,39,ch.functional,'score-chord')}${svgText(x0+10,55,ch.name,'score-chord-name')}${svgText(x0+6,12,start+k+1,'bar-number')}<line x1="${xend}" y1="55" x2="${xend}" y2="108" class="barline"/><line x1="${x0+15}" y1="48" x2="${x0+15}" y2="145" class="bar-playhead" data-playhead="${start+k}" data-xstart="${x0+15}" data-span="${barWidth-25}"/>`;
notes.forEach((note,j)=>{const x=positions[j];out+=`<g data-perf-note="${start+k}-${j}" class="engraved-note"><rect x="${x-12}" y="57" width="25" height="86" rx="5" class="note-wash"/>${svgText(x,84,note.degree,'note-digit','text-anchor="middle"')}`;if(note.octave)out+=`<circle cx="${x}" cy="${note.octave>0?57:102}" r="2.1" class="octave-dot"/>`;if(note.beats===1.5)out+=`<circle cx="${x+15}" cy="77" r="2" class="octave-dot"/>`;if(note.beats<1){out+=`<line x1="${x-8}" y1="92" x2="${x+8}" y2="92" class="duration-line"/>`;if(note.beats<=.25)out+=`<line x1="${x-8}" y1="97" x2="${x+8}" y2="97" class="duration-line"/>`;}for(let d=1;d<Math.floor(note.beats);d++)out+=svgText(x+d*inner/4,84,'−','note-digit','text-anchor="middle"');out+=svgText(x,130,note.lyric||'','note-lyric','text-anchor="middle"')+'</g>';if(note.beats===.5&&notes[j+1]?.beats===.5){const t=notes.slice(0,j+1).reduce((s,n)=>s+n.beats,0);if(t%1!==0)out+=`<line x1="${x-8}" y1="92" x2="${positions[j+1]+8}" y2="92" class="duration-line"/>`}});out+='</g>'});return `<svg viewBox="0 0 ${width} 165" class="score-system" xmlns="http://www.w3.org/2000/svg" aria-label="第 ${start+1} 至 ${start+bars.length} 小节">${out}</svg>`}
renderPerformance=function(){const perLine=innerWidth<700?2:4,width=perLine===2?640:1100;let index=0;$('#performanceScore').innerHTML=`<div class="engraved-title"><h2>${esc(performanceScore.title)}</h2><p>${esc(performanceScore.credit)}</p><div>1 = ${esc(perfRoot()[0])}　　4/4　　♩ = ${+$('#performanceTempo').value||66}　　轻柔、克制地</div></div>`+performanceScore.sections.map(section=>{const start=index;index+=section.bars.length;let systems='';for(let i=0;i<section.bars.length;i+=perLine)systems+=systemSVG(section.bars.slice(i,i+perLine),start+i,perLine,width);return `<section class="engraved-section"><h3>${esc(section.name)} <small>${section.type==='vocal'?'演唱 · 和弦伴奏':'器乐 · 旋律 + 伴奏'}</small></h3>${systems}</section>`}).join('');perfKeys();perfBarUI(Math.min(performanceBar,index-1));};
const priorBarUI=perfBarUI;perfBarUI=function(index){priorBarUI(index);const bar=flattenScore()[index];if(!bar)return;const chord=perfChord(bar);$('#performanceChord').textContent=chord.functional+' → '+chord.name;const mode=$('#arrangementMode').value,style=mode==='written'?(bar.style||'broken'):mode;$('#performanceMode').textContent=(style==='block'?'柱式':style==='mixed'?'柱式 + 分解':'分解')+(bar.type==='vocal'?'和弦 · 演唱段':'和弦 + 器乐旋律');if(performancePlaying&&$('#scoreFollow').checked){const el=$(`[data-perf-bar="${index}"]`);if(el){const viewport=$('#performanceScore'),rect=el.getBoundingClientRect(),area=viewport.getBoundingClientRect();if(rect.top<area.top+55||rect.bottom>area.bottom-25)viewport.scrollTo({top:viewport.scrollTop+rect.top-area.top-65,behavior:'smooth'})}}};
// One event plan powers playback and offline export, so arrangement and notation agree.
function songEventPlan(from=0,mode='written',guide=false){let elapsed=0;const events=[];flattenScore().slice(from).forEach((bar,k)=>{const index=from+k,notes=perfChord(bar).notes,style=mode==='written'?(bar.style||'broken'):mode,energy=index<12?.68:index>=36?.56:.76;
 const addChord=(at,midi,len,j)=>events.push({at:elapsed+at,duration:len,midi,kind:'chord',bar:index,id:`performance-chord-${index}-${j}`,gain:energy*.7});
 if(style==='block')notes.forEach((m,j)=>addChord(0,m,3.65,j));else{if(style==='mixed')notes.forEach((m,j)=>addChord(0,m,1.75,'block-'+j));const start=style==='mixed'?2:0;for(let t=start;t<4;t+=.5){const q=(t-start)*2,position=[0,1,2,notes.length-1][q%4];addChord(t,notes[position],.9,'arp-'+q)}}
 let beat=0;bar.melody.forEach((note,j)=>{events.push({at:elapsed+beat,duration:note.beats*.92,midi:note.degree?perfMelody(note):null,kind:'melody',audible:note.degree&&(bar.type!=='vocal'||guide),bar:index,note:j,id:`performance-melody-${index}-${j}`,gain:energy});beat+=note.beats});elapsed+=4});return {events,duration:elapsed}}
let scoreAnimation=0,scoreClock=null;const oldStopPerformance=stopPerformance;stopPerformance=function(){cancelAnimationFrame(scoreAnimation);scoreClock=null;oldStopPerformance();$$('.engraved-bar').forEach(b=>b.classList.remove('sounding'));};
function animateScore(){if(!performancePlaying||!scoreClock)return;const elapsed=(performance.now()-scoreClock.start)/scoreClock.beat,index=scoreClock.from+Math.floor(elapsed/4),fraction=(elapsed%4)/4;$$('[data-playhead]').forEach(line=>{if(+line.dataset.playhead===index){const x=+line.dataset.xstart+fraction*+line.dataset.span;line.setAttribute('x1',x);line.setAttribute('x2',x)}});scoreAnimation=requestAnimationFrame(animateScore)}
$('#performancePlay').onclick=async()=>{if(performancePlaying)return;stopPerformance();stopSong();const run=performanceRun;try{await audio()}catch{$('#performanceState').textContent='无法开启音频，请检查浏览器声音权限';return}if(run!==performanceRun)return;performancePlaying=true;$('#performancePlay').disabled=true;$('#performanceStop').disabled=false;const beat=60000/Math.max(40,Math.min(160,+$('#performanceTempo').value||66)),from=performanceBar,plan=songEventPlan(from,$('#arrangementMode').value,$('#performanceGuide').checked),bars=flattenScore();scoreClock={start:performance.now(),beat,from};animateScore();
for(let index=from;index<bars.length;index++)perfSchedule(()=>{perfBarUI(index);$('#performanceState').textContent=`第 ${index+1} / ${bars.length} 小节 · ${bars[index].section}`},(index-from)*4*beat);
plan.events.forEach(event=>{perfSchedule(()=>{if(event.kind==='melody')$(`[data-perf-note="${event.bar}-${event.note}"]`)?.classList.add('playing');if(event.midi!==null&&(event.kind==='chord'||event.audible)){noteOn(event.id,event.midi-(octave+1)*12).then(()=>{const v=voices.get(event.id);if(v){const t=ctx.currentTime;v.g.gain.cancelScheduledValues(t);v.g.gain.setValueAtTime(0,t);v.g.gain.linearRampToValueAtTime(.065*event.gain,t+.025)}})}},event.at*beat);perfSchedule(()=>{noteOff(event.id);if(event.kind==='melody')$(`[data-perf-note="${event.bar}-${event.note}"]`)?.classList.remove('playing')},(event.at+event.duration)*beat)});perfSchedule(()=>{stopPerformance();$('#performanceState').textContent='演奏完成 · 尾奏已收束'},plan.duration*beat+400)};
$('#performanceStop').onclick=()=>stopPerformance();$('#arrangementMode').onchange=()=>{stopPerformance();perfBarUI(performanceBar)};$('#performanceReset').onclick=()=>{stopPerformance();perfBarUI(0);$('#performanceScore').scrollTop=0};$('#performanceScore').onkeydown=e=>{if(['Enter',' '].includes(e.key)){const bar=e.target.closest('[data-perf-bar]');if(bar){e.preventDefault();stopPerformance();perfBarUI(+bar.dataset.perfBar)}}};
$('#performanceSong').onchange=e=>{stopPerformance();if(e.target.value==='import'){$('#scoreImport').hidden=false;$('#scoreImport').scrollIntoView({behavior:'smooth'})}else{performanceScore=composedSong;performanceBar=0;$('#scoreImport').hidden=true;renderPerformance()}};$('#scoreTemplate').onclick=()=>{$('#scoreData').value=JSON.stringify(composedSong,null,2)};
const priorValidate=validateScore;validateScore=function(raw){const clean=priorValidate(raw);clean.sections.forEach((section,i)=>section.bars.forEach((bar,j)=>{const source=raw.sections[i].bars[j];bar.style=['block','mixed','broken'].includes(source.style)?source.style:'broken';bar.melody.forEach((note,k)=>note.lyric=typeof source.melody[k].lyric==='string'?source.melody[k].lyric.slice(0,2):'')}));return clean};
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
$('#downloadSongData').onclick=()=>downloadBlob(new Blob([JSON.stringify(performanceScore,null,2)],{type:'application/json'}),performanceScore.title+'.json');
$('#downloadScore').onclick=()=>{let y=140,index=0,content=svgText(550,55,performanceScore.title,'export-title','text-anchor="middle"')+svgText(550,88,`1=${perfRoot()[0]}　4/4　♩=${+$('#performanceTempo').value||66}　原创词曲与编配`,'export-meta','text-anchor="middle"');performanceScore.sections.forEach(section=>{content+=svgText(30,y,section.name,'export-section');y+=20;for(let i=0;i<section.bars.length;i+=4){const svg=systemSVG(section.bars.slice(i,i+4),index+i,4);content+=`<g transform="translate(0 ${y})">${svg.replace(/<svg[^>]*>/,'').replace('</svg>','')}</g>`;y+=175}index+=section.bars.length;y+=30});const css='.score-chord{font:18px sans-serif;fill:#4b775e}.score-chord-name{font:12px sans-serif;fill:#66766a}.note-digit{font:28px serif;fill:#202b25}.note-lyric{font:17px sans-serif;fill:#303a33}.bar-number{font:10px sans-serif;fill:#777}.barline,.duration-line{stroke:#26352b;stroke-width:1.4}.octave-dot{fill:#26352b}.note-wash,.bar-wash,.bar-playhead{display:none}.export-title{font:32px sans-serif;fill:#243c2d}.export-meta{font:16px sans-serif;fill:#58685c}.export-section{font:20px sans-serif;fill:#243c2d}';downloadBlob(new Blob([`<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="${y}" viewBox="0 0 1100 ${y}"><rect width="1100" height="${y}" fill="white"/><style>${css}</style>${content}</svg>`],{type:'image/svg+xml'}),performanceScore.title+'-完整简谱.svg')};
$('#downloadPiano').onclick=async()=>{const button=$('#downloadPiano');button.disabled=true;button.textContent='正在渲染钢琴音频…';try{const beat=60/(+$('#performanceTempo').value||66),plan=songEventPlan(0,$('#arrangementMode').value,true),rate=22050,offline=new OfflineAudioContext(1,Math.ceil((plan.duration*beat+2)*rate),rate);plan.events.filter(e=>e.midi!==null&&(e.kind==='chord'||e.audible)).forEach(e=>{const t=e.at*beat,d=e.duration*beat,g=offline.createGain();g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.045*e.gain,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+Math.max(.05,d));g.connect(offline.destination);[1,2,3].forEach((h,i)=>{const o=offline.createOscillator(),a=offline.createGain();o.frequency.value=440*2**((e.midi-69)/12)*h;a.gain.value=[1,.22,.06][i];o.connect(a);a.connect(g);o.start(t);o.stop(t+d+.05)})});const rendered=await offline.startRendering(),data=rendered.getChannelData(0),buffer=new ArrayBuffer(44+data.length*2),view=new DataView(buffer),write=(at,s)=>{[...s].forEach((c,i)=>view.setUint8(at+i,c.charCodeAt(0)))};write(0,'RIFF');view.setUint32(4,36+data.length*2,true);write(8,'WAVE');write(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,rate,true);view.setUint32(28,rate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);write(36,'data');view.setUint32(40,data.length*2,true);data.forEach((v,i)=>view.setInt16(44+i*2,Math.max(-1,Math.min(1,v))*32767,true));downloadBlob(new Blob([buffer],{type:'audio/wav'}),performanceScore.title+'-钢琴旋律示范.wav')}catch(e){$('#performanceState').textContent='音频导出失败：'+e.message}finally{button.disabled=false;button.textContent='导出钢琴示范 WAV'}};
$('#scoreImport p:nth-of-type(2)').textContent='degree 为简谱 1～7（0 为休止），octave 为 -1/0/1，beats 为时值，lyric 为单字；每小节合计 4 拍。支持基础调内和弦与本站曲谱所用的扩展和弦；style 可为 block、broken 或 mixed。';
let scoreWidthClass=innerWidth<700;window.addEventListener('resize',()=>{const narrow=innerWidth<700;if(narrow!==scoreWidthClass){scoreWidthClass=narrow;stopPerformance();renderPerformance()}});renderPerformance();

